def validate_in_memory_origins(cfg,truth,pol,ifos):
    if [i.name for i in ifos]!=cfg["detectors"] or len(set(id(i) for i in ifos))!=2:raise ValueError("Synthetic detector identity required")
    origin=_POLARIZATION_ORIGINS.get(id(pol))
    if origin is None or origin["object"] is not pol or origin["truth"]!=truth_digest(truth):raise ValueError("Only polarizations generated here from this synthetic truth")
    if {k:array_digest(a) for k,a in pol.items()}!=origin["hashes"]:raise ValueError("Generated polarization was modified")
    for i in ifos:
        o=_SYNTHETIC_IFOS.get(id(i))
        if o is None or o["object"] is not i or o["consumed"]:raise ValueError("Foreign/reused detector object prohibited")
        if array_digest(i.strain_data.frequency_domain_strain)!=o["noise"] or array_digest(i.power_spectral_density_array)!=o["PSD"]:raise ValueError("Synthetic noise/PSD was replaced")
        if array_digest(i.frequency_array)!=o["frequency"] or float(i.strain_data.start_time)!=o["start"]:raise ValueError("Synthetic grid/time replaced")
    return True

    validate_config(cfg)
    if noise_kind not in ("ZERO","SEEDED_GAUSSIAN"):raise ValueError("Only constructed synthetic noise allowed")
    g=cfg["grid"];duration=g["duration_s"];start=cfg["geometry"]["geocent_time"]-g["geocenter_seconds_after_segment_start"]
    expected_f=np.fft.rfftfreq(int(duration*g["sample_rate_hz"]),d=1/g["sample_rate_hz"])
    if not np.array_equal(f,expected_f):raise ValueError("Only registered synthetic frequency grid")
    expected_psd,_=analytic_psd(f,cfg)
    if not np.array_equal(psd,expected_psd):raise ValueError("Only the analytic PSD computed here; no foreign arrays")
    mask=np.isfinite(psd);rng=np.random.default_rng(cfg["noise_seed"])
    ifos=bilby.gw.detector.InterferometerList(cfg["detectors"]);noise={}
    for ifo in ifos:
        n=np.zeros_like(f,dtype=complex)
        if noise_kind=="SEEDED_GAUSSIAN":
            n[mask]=np.sqrt(duration*psd[mask]/4)*(rng.normal(size=mask.sum())+1j*rng.normal(size=mask.sum()))
        ifo.minimum_frequency=g["minimum_frequency_hz"];ifo.maximum_frequency=g["maximum_frequency_hz"]
        ifo.power_spectral_density=bilby.gw.detector.PowerSpectralDensity(frequency_array=f,psd_array=psd)
        ifo.set_strain_data_from_frequency_domain_strain(n,sampling_frequency=g["sample_rate_hz"],duration=duration,start_time=start)
        noise[ifo.name]=n.copy()
        _SYNTHETIC_IFOS[id(ifo)]={"object":ifo,"consumed":False,"noise":array_digest(ifo.strain_data.frequency_domain_strain),
            "PSD":array_digest(ifo.power_spectral_density_array),"frequency":array_digest(ifo.frequency_array),"start":float(ifo.strain_data.start_time)}
    return ifos,noise

def inject(cfg,truth,pol,ifos):
    validate_truth(cfg,truth)
    validate_in_memory_origins(cfg,truth,pol,ifos)

signal={i.name:i.get_detector_response(scaled,actual) for i in ifos}
for i in ifos:
    i.inject_signal(parameters=actual,injection_polarizations=scaled,raise_error=True)
    if not np.allclose(i.strain_data.frequency_domain_strain,before_data[i.name]+signal[i.name],rtol=1e-12,atol=1e-30):
        raise ValueError("Injection is not exact additive response")
for i in ifos:_SYNTHETIC_IFOS[id(i)]["consumed"]=True
return actual,scaled,signal,{"network_optimal_SNR":math.sqrt(sum(snr2)),"scale_factor":factor,
                            "noise":"constructed synthetic only","units":"one-sided PSD strain^2/Hz; Fourier strain seconds",
                            "SNR_kind":"full IMR network optimal, not ringdown"}

def inside(p,root):return p==root or root in p.parents
def audit(event,args):
    if event in ("socket.connect","socket.connect_ex","subprocess.Popen","os.system"):
        blocked.append({"event":event,"reason":"no network/process launch permitted in qualification child"})
        raise PermissionError("Synthetic isolation blocks "+event)
    if event=="open" and args and isinstance(args[0],(str,bytes,os.PathLike)):
        p=Path(os.fsdecode(args[0])).resolve()
        mode=args[1] if len(args)>1 else "r";flags=args[2] if len(args)>2 and isinstance(args[2],int) else 0
        writing=(isinstance(mode,str) and any(c in mode for c in "wax+")) or bool(flags&(os.O_WRONLY|os.O_RDWR|os.O_CREAT|os.O_TRUNC|os.O_APPEND))
        permitted=inside(p,run) if writing else (inside(p,ROOT) or any(inside(p,r) for r in runtime_roots) or p in (Path("/dev/null"),Path("/etc/localtime")))
        if str(p).startswith("/mnt/"):filesystem.append({"path":str(p),"write":writing,"allowed":permitted})
        if not permitted:
            blocked.append({"event":event,"path":str(p),"write":writing})
            raise PermissionError("Synthetic file allowlist blocks "+str(p))
sys.addaudithook(audit)

def tracked_bbh(*args,**kwargs):
    if counter[0]>=contract["max_native_calls"]:raise RuntimeError("Native call cap reached")
    dictionary=kwargs["lal_waveform_dictionary"]
    params={n:float(getattr(ls,"SimInspiralWaveformParamsLookup"+n)(dictionary)) for n in ("DTau220","DTau440","DOmega220","DOmega440")}
    if any(params[n]!=0.0 for n in ("DTau440","DOmega220","DOmega440")):raise AssertionError("Fixed deformation leaked")
    if kwargs["maximum_frequency"]!=4096 or len(args[0])!=131073:raise AssertionError("Generation grid was not forwarded")
    if kwargs["waveform_approximant"]!="pSEOBNRv4HM_PA":raise AssertionError("Wrong native family")
    if not any(dictionary is x for x in native_dictionaries):raise AssertionError("Dictionary provenance absent")
    trace.append({"ordinal":len(trace)+1,"deformations":params,"generation_bins":len(args[0]),
                  "generation_fmax":kwargs["maximum_frequency"],"family":kwargs["waveform_approximant"]})
    return old_bbh(*args,**kwargs)
bilby.gw.source.lal_binary_black_hole=tracked_bbh
